text:
도장 사용법




대응 이론: Ch03 딥러닝의 학습
학번을 입력하면 나만의 문제가 나옵니다. 새 문제 버튼으로 무한 반복 연습.
이 주차는 계산기가 필요합니다. 지수 e^x 와 자연로그 ln 을 쓰는 문제가 있습니다.
유형은 8개 — [기본] 3 → [응용] 2 → [도전] 3.
훈련 기준: 각 유형에서 연속 3문제 무실수.
// mulberry32 — 문제 번호(시드)가 같으면 항상 같은 문제가 생성된다
dojoRng = function (seed) {
  let a = (seed * 7919 + 104729) &gt;&gt;&gt; 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a &gt;&gt;&gt; 15), 1 | a);
    t = (t + Math.imul(t ^ (t &gt;&gt;&gt; 7), 61 | t)) ^ t;
    return ((t ^ (t &gt;&gt;&gt; 14)) &gt;&gt;&gt; 0) / 4294967296;
  };
}
dojoInt = (rng, lo, hi) =&gt; lo + Math.floor(rng() * (hi - lo + 1))
dojoPick = (rng, arr) =&gt; arr[Math.floor(rng() * arr.length)]
// 정답 비교 — tol 이내면 정답 처리 (학생의 반올림 오차 허용)
dojoOk = (user, answer, tol = 0.005) =&gt;
  user !== null && user !== undefined && Number.isFinite(user) && Math.abs(user - answer) &lt;= tol
dojoMark = (label, ok, answerShown) =&gt; `
  &lt;div style="display:flex;align-items:center;gap:0.5em;padding:0.25em 0;"&gt;
    &lt;span style="font-size:1.1em;"&gt;${ok ? "✅" : "❌"}&lt;/span&gt;
    &lt;span style="font-weight:600;"&gt;${label}&lt;/span&gt;
    &lt;span style="color:${ok ? "#2E7D32" : "#8C1515"};"&gt;
      ${ok ? "정답" : (answerShown != null ? "오답 — 다시 계산해 보세요" : "오답")}
    &lt;/span&gt;
  &lt;/div&gt;`
// 문제 카드
dojoProblem = (title, bodyHtml) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;border:1.5px solid #8C1515;border-radius:8px;
    overflow:hidden;margin:0.6em 0;max-width:720px;"&gt;
    &lt;div style="background:#8C1515;color:white;padding:0.4em 0.9em;font-weight:700;font-size:0.95em;"&gt;
      ${title}
    &lt;/div&gt;
    &lt;div style="padding:0.7em 0.9em;line-height:1.9;font-size:0.95em;"&gt;${bodyHtml}&lt;/div&gt;
  &lt;/div&gt;`
// 채점 결과 카드
dojoResult = (marks, allOk) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;border-radius:8px;max-width:720px;margin:0.4em 0;
    padding:0.6em 0.9em;font-size:0.92em;
    background:${allOk ? "#E8F5E9" : "#FFF8E1"};
    border:1.5px solid ${allOk ? "#2E7D32" : "#D4A017"};"&gt;
    ${marks.join("")}
    &lt;div style="margin-top:0.35em;font-weight:700;color:${allOk ? "#2E7D32" : "#B8860B"};"&gt;
      ${allOk ? "🎉 전부 정답! 문제 번호를 바꿔 한 번 더 연습해 보세요." : "빨간 항목을 다시 풀어 보세요. 막히면 풀이 보기를 켜세요."}
    &lt;/div&gt;
  &lt;/div&gt;`
// 풀이 카드
dojoSolution = (stepsHtml) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;border-radius:8px;max-width:720px;margin:0.4em 0;
    padding:0.7em 0.9em;background:#E3F2FD;border:1.5px solid #1565C0;
    line-height:2.0;font-size:0.92em;"&gt;
    &lt;div style="font-weight:700;color:#1565C0;margin-bottom:0.2em;"&gt;풀이&lt;/div&gt;
    ${stepsHtml}
  &lt;/div&gt;`
// FNV-1a — 학번 문자열을 정수로. 사람마다 다른 문제가 나오게 하는 출발점.
dojoHash = function (str) {
  let h = 2166136261 &gt;&gt;&gt; 0;
  const s = String(str);
  for (let i = 0; i &lt; s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619) &gt;&gt;&gt; 0;
  }
  return h &gt;&gt;&gt; 0;
}
// (학번, 주차, 유형, 라운드) → 문제 번호.
// 학번이 다르면 다른 문제, 같은 학번·같은 라운드면 항상 같은 문제(재현 가능).
dojoSeed = function (sid, week, type, round) {
  const key = (sid && String(sid).trim()) ? String(sid).trim() : "guest";
  return (dojoHash(key + "|" + week + "|" + type + "|" + round) % 99999) + 1;
}
// 학번 입력 — 브라우저에 저장되어 모든 도장 페이지에서 유지된다.
viewof dojoSid = Inputs.text({
  label: "학번",
  placeholder: "예: 202312345",
  value: (() =&gt; { try { return localStorage.getItem("dojoSid") || ""; } catch (e) { return ""; } })(),
  width: 260
})
{
  try { localStorage.setItem("dojoSid", dojoSid || ""); } catch (e) {}
  const named = dojoSid && dojoSid.trim();
  return html`&lt;div style="font-family:'Pretendard',sans-serif;font-size:0.85em;
    padding:0.45em 0.8em;border-radius:6px;max-width:720px;margin:0.1em 0 0.9em;
    background:${named ? "#E8F5E9" : "#FFF8E1"};
    border:1px solid ${named ? "#A5D6A7" : "#E8D9A0"};color:${named ? "#2E7D32" : "#8A6D1B"};"&gt;
    ${named
      ? `학번 &lt;strong&gt;${dojoSid.trim()}&lt;/strong&gt; 기준으로 문제가 생성됩니다 — 옆 사람과 다른 문제가 나옵니다.`
      : `학번을 입력하면 &lt;strong&gt;나만의 문제 세트&lt;/strong&gt;가 만들어집니다. (비워 두면 공용 연습 문제)`}
  &lt;/div&gt;`;
}
// "새 문제" 버튼 + 문제 코드 표시를 한 줄로 묶는 헤더
dojoBar = (code) =&gt; html`
  &lt;div style="font-family:'Pretendard',sans-serif;font-size:0.82em;color:#666;
    margin:-0.3em 0 0.5em;"&gt;
    문제 코드 &lt;code style="background:#F1F3F5;padding:0.1em 0.4em;border-radius:4px;
    color:#8C1515;font-weight:700;"&gt;${code}&lt;/code&gt;
    &lt;span style="color:#999;"&gt; — 질문할 때 이 코드를 알려주세요&lt;/span&gt;
  &lt;/div&gt;`

유형 A — MSE 계산 [기본]

viewof rA_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







rA_seed = dojoSeed(dojoSid, 3, "A", rA_round)







rA = {
  const rng = dojoRng(rA_seed);
  const n = dojoInt(rng, 4, 5);
  const ys = [], hs = [];
  for (let i = 0; i &lt; n; i++) {
    const y = dojoInt(rng, 150, 190);
    const e = dojoInt(rng, -6, 6);
    ys.push(y); hs.push(y - e);
  }
  const errs = ys.map((y, i) =&gt; y - hs[i]);
  const sq = errs.map(e =&gt; e * e);
  const sum = sq.reduce((a, b) =&gt; a + b, 0);
  return { n, ys, hs, errs, sq, sum, mse: Math.round(sum / n * 1000) / 1000 };
}







dojoBar(`A-${rA_seed}`)







dojoProblem(`문제 A — 평균제곱오차`, `
  키(cm)를 예측하는 모형의 결과가 다음과 같다.
  &lt;div style="margin:0.5em 0;"&gt;
  &lt;table style="border-collapse:collapse;font-size:0.95em;"&gt;
    &lt;tr style="background:#8C1515;color:#fff;"&gt;
      &lt;th style="padding:0.25em 0.8em;"&gt;i&lt;/th&gt;
      ${rA.ys.map((_, i) =&gt; `&lt;th style="padding:0.25em 0.8em;"&gt;${i + 1}&lt;/th&gt;`).join("")}
    &lt;/tr&gt;
    &lt;tr&gt;&lt;td style="padding:0.25em 0.8em;border:1px solid #ddd;"&gt;&lt;strong&gt;실제 y&lt;/strong&gt;&lt;/td&gt;
      ${rA.ys.map(v =&gt; `&lt;td style="padding:0.25em 0.8em;border:1px solid #ddd;text-align:center;"&gt;${v}&lt;/td&gt;`).join("")}&lt;/tr&gt;
    &lt;tr&gt;&lt;td style="padding:0.25em 0.8em;border:1px solid #ddd;"&gt;&lt;strong&gt;예측 ŷ&lt;/strong&gt;&lt;/td&gt;
      ${rA.hs.map(v =&gt; `&lt;td style="padding:0.25em 0.8em;border:1px solid #ddd;text-align:center;"&gt;${v}&lt;/td&gt;`).join("")}&lt;/tr&gt;
  &lt;/table&gt;
  &lt;/div&gt;
  &lt;strong&gt;MSE = (1/n)·Σ(yᵢ − ŷᵢ)²&lt;/strong&gt; 를 구하라. (소수 셋째 자리까지)`)







viewof rA_ans = Inputs.number({ label: "MSE =", step: 0.001 })
viewof rA_grade = Inputs.toggle({ label: "채점", value: false })
viewof rA_show = Inputs.toggle({ label: "풀이 보기", value: false })























rA_grade ? dojoResult(
  [dojoMark("MSE", dojoOk(rA_ans, rA.mse, 0.0015))],
  dojoOk(rA_ans, rA.mse, 0.0015)
) : html``







rA_show ? dojoSolution(`
  ① 각 오차와 그 제곱:&lt;br&gt;
  ${rA.ys.map((y, i) =&gt; `&nbsp;&nbsp;(${y} − ${rA.hs[i]}) = ${rA.errs[i]} → ${rA.errs[i]}² = ${rA.sq[i]}`).join("&lt;br&gt;")}&lt;br&gt;
  ② 제곱합 = ${rA.sq.join(" + ")} = &lt;strong&gt;${rA.sum}&lt;/strong&gt;&lt;br&gt;
  ③ MSE = ${rA.sum} / ${rA.n} = &lt;strong&gt;${rA.mse}&lt;/strong&gt;&lt;br&gt;
  &lt;span style="color:#555;"&gt;제곱하므로 오차의 부호는 사라지고, 큰 오차에 더 큰 벌칙이 간다.&lt;/span&gt;`) : html``

유형 B — Softmax 확률 [기본]

viewof rB_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







rB_seed = dojoSeed(dojoSid, 3, "B", rB_round)







rB = {
  const rng = dojoRng(rB_seed);
  const z = [dojoInt(rng, -20, 30) / 10, dojoInt(rng, -20, 30) / 10, dojoInt(rng, -20, 30) / 10];
  const ex = z.map(v =&gt; Math.exp(v));
  const s = ex.reduce((a, b) =&gt; a + b, 0);
  const p = ex.map(v =&gt; Math.round(v / s * 1000) / 1000);
  return { z, ex, s, p, argmax: p.indexOf(Math.max(...p)) + 1 };
}







dojoBar(`B-${rB_seed}`)







dojoProblem(`문제 B — Softmax`, `
  3개 클래스 분류에서 출력층의 값이 다음과 같다.
  &lt;div style="text-align:center;margin:0.5em 0;font-size:1.05em;"&gt;
  &lt;strong&gt;z₁ = ${rB.z[0]}, &nbsp; z₂ = ${rB.z[1]}, &nbsp; z₃ = ${rB.z[2]}&lt;/strong&gt;
  &lt;/div&gt;
  Softmax(zₖ) = e^zₖ / (e^z₁ + e^z₂ + e^z₃) 으로
  각 클래스의 확률을 &lt;strong&gt;소수 셋째 자리까지&lt;/strong&gt; 구하라.`)







viewof rB_p1 = Inputs.number({ label: "p₁ =", step: 0.001 })
viewof rB_p2 = Inputs.number({ label: "p₂ =", step: 0.001 })
viewof rB_p3 = Inputs.number({ label: "p₃ =", step: 0.001 })
viewof rB_grade = Inputs.toggle({ label: "채점", value: false })
viewof rB_show = Inputs.toggle({ label: "풀이 보기", value: false })





































rB_grade ? dojoResult(
  [dojoMark("p₁", dojoOk(rB_p1, rB.p[0], 0.0015)),
   dojoMark("p₂", dojoOk(rB_p2, rB.p[1], 0.0015)),
   dojoMark("p₃", dojoOk(rB_p3, rB.p[2], 0.0015))],
  dojoOk(rB_p1, rB.p[0], 0.0015) && dojoOk(rB_p2, rB.p[1], 0.0015) && dojoOk(rB_p3, rB.p[2], 0.0015)
) : html``







rB_show ? dojoSolution(`
  ① 각 z에 지수를 취한다:&lt;br&gt;
  &nbsp;&nbsp;e^${rB.z[0]} = ${rB.ex[0].toFixed(4)}, &nbsp;
  e^${rB.z[1]} = ${rB.ex[1].toFixed(4)}, &nbsp;
  e^${rB.z[2]} = ${rB.ex[2].toFixed(4)}&lt;br&gt;
  ② 분모(합) = ${rB.ex.map(v =&gt; v.toFixed(4)).join(" + ")} = &lt;strong&gt;${rB.s.toFixed(4)}&lt;/strong&gt;&lt;br&gt;
  ③ 각각을 합으로 나눈다:&lt;br&gt;
  &nbsp;&nbsp;p₁ = ${rB.ex[0].toFixed(4)}/${rB.s.toFixed(4)} = &lt;strong&gt;${rB.p[0].toFixed(3)}&lt;/strong&gt;&lt;br&gt;
  &nbsp;&nbsp;p₂ = ${rB.ex[1].toFixed(4)}/${rB.s.toFixed(4)} = &lt;strong&gt;${rB.p[1].toFixed(3)}&lt;/strong&gt;&lt;br&gt;
  &nbsp;&nbsp;p₃ = ${rB.ex[2].toFixed(4)}/${rB.s.toFixed(4)} = &lt;strong&gt;${rB.p[2].toFixed(3)}&lt;/strong&gt;&lt;br&gt;
  &lt;span style="color:#555;"&gt;검산: 세 확률의 합은 항상 1이다 (반올림 오차 제외).
  가장 큰 z(=z${["₁","₂","₃"][rB.argmax - 1]})가 가장 높은 확률을 받는다.&lt;/span&gt;`) : html``

유형 C — 이진 교차 엔트로피 (1건) [기본]

viewof rC_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







rC_seed = dojoSeed(dojoSid, 3, "C", rC_round)







rC = {
  const rng = dojoRng(rC_seed);
  const y = dojoInt(rng, 0, 1);
  const p = dojoInt(rng, 5, 95) / 100;
  const used = y === 1 ? p : 1 - p;
  return { y, p, used, loss: Math.round(-Math.log(used) * 1000) / 1000 };
}







dojoBar(`C-${rC_seed}`)







dojoProblem(`문제 C — 이진 교차 엔트로피`, `
  이진 분류에서 어떤 데이터 한 건의 실제 정답이 &lt;strong&gt;y = ${rC.y}&lt;/strong&gt; 이고,
  모형이 출력한 확률(클래스 1일 확률)이 &lt;strong&gt;ŷ = ${rC.p}&lt;/strong&gt; 이다.&lt;br&gt;
  이 한 건의 손실을 구하라.
  &lt;div style="text-align:center;margin:0.5em 0;"&gt;
  &lt;strong&gt;L = −[ y·ln(ŷ) + (1−y)·ln(1−ŷ) ]&lt;/strong&gt;
  &lt;/div&gt;
  (ln 은 자연로그, 소수 셋째 자리까지)`)







viewof rC_ans = Inputs.number({ label: "L =", step: 0.001 })
viewof rC_grade = Inputs.toggle({ label: "채점", value: false })
viewof rC_show = Inputs.toggle({ label: "풀이 보기", value: false })























rC_grade ? dojoResult(
  [dojoMark("손실 L", dojoOk(rC_ans, rC.loss, 0.0015))],
  dojoOk(rC_ans, rC.loss, 0.0015)
) : html``







rC_show ? dojoSolution(`
  ① y = ${rC.y} 이므로 ${rC.y === 1
    ? "둘째 항 (1−y)·ln(1−ŷ) 이 0이 되어 사라진다. 남는 것은 −ln(ŷ)."
    : "첫째 항 y·ln(ŷ) 이 0이 되어 사라진다. 남는 것은 −ln(1−ŷ)."}&lt;br&gt;
  ② L = −ln(${rC.used}) = −(${Math.log(rC.used).toFixed(4)}) = &lt;strong&gt;${rC.loss.toFixed(3)}&lt;/strong&gt;&lt;br&gt;
  &lt;span style="color:#555;"&gt;정답 클래스에 부여한 확률이 ${rC.used} 였다.
  이 값이 1에 가까울수록 손실은 0에, 0에 가까울수록 손실은 무한대로 커진다 —
  &lt;strong&gt;확신에 찬 오답&lt;/strong&gt;에 큰 벌칙을 주는 것이 교차 엔트로피의 성질이다.&lt;/span&gt;`) : html``

유형 D — Softmax + 다중 클래스 교차 엔트로피 [응용]

viewof rD_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







rD_seed = dojoSeed(dojoSid, 3, "D", rD_round)







rD = {
  const rng = dojoRng(rD_seed);
  const z = [dojoInt(rng, -15, 25) / 10, dojoInt(rng, -15, 25) / 10, dojoInt(rng, -15, 25) / 10];
  const ex = z.map(v =&gt; Math.exp(v));
  const s = ex.reduce((a, b) =&gt; a + b, 0);
  const p = ex.map(v =&gt; v / s);
  const k = dojoInt(rng, 0, 2);
  return {
    z, ex, s, k,
    pk: Math.round(p[k] * 1000) / 1000,
    loss: Math.round(-Math.log(p[k]) * 1000) / 1000
  };
}







dojoBar(`D-${rD_seed}`)







dojoProblem(`문제 D — 다중 클래스 손실`, `
  3개 클래스 분류에서 출력층 값이
  &lt;strong&gt;z₁ = ${rD.z[0]}, z₂ = ${rD.z[1]}, z₃ = ${rD.z[2]}&lt;/strong&gt; 이고,
  이 데이터의 &lt;strong&gt;정답은 클래스 ${rD.k + 1}&lt;/strong&gt; 이다.&lt;br&gt;
  ① 정답 클래스의 Softmax 확률, ② 교차 엔트로피 손실
  &lt;strong&gt;L = −ln(ŷ&lt;sub&gt;정답&lt;/sub&gt;)&lt;/strong&gt; 을 구하라. (소수 셋째 자리까지)`)







viewof rD_ans_p = Inputs.number({ label: "정답 클래스 확률 =", step: 0.001 })
viewof rD_ans_l = Inputs.number({ label: "L =", step: 0.001 })
viewof rD_grade = Inputs.toggle({ label: "채점", value: false })
viewof rD_show = Inputs.toggle({ label: "풀이 보기", value: false })






























rD_grade ? dojoResult(
  [dojoMark("정답 클래스 확률", dojoOk(rD_ans_p, rD.pk, 0.0015)),
   dojoMark("손실 L", dojoOk(rD_ans_l, rD.loss, 0.0025))],
  dojoOk(rD_ans_p, rD.pk, 0.0015) && dojoOk(rD_ans_l, rD.loss, 0.0025)
) : html``







rD_show ? dojoSolution(`
  ① 지수: e^${rD.z[0]} = ${rD.ex[0].toFixed(4)}, e^${rD.z[1]} = ${rD.ex[1].toFixed(4)},
     e^${rD.z[2]} = ${rD.ex[2].toFixed(4)} → 합 = &lt;strong&gt;${rD.s.toFixed(4)}&lt;/strong&gt;&lt;br&gt;
  &nbsp;&nbsp;정답은 클래스 ${rD.k + 1} 이므로
     ŷ = ${rD.ex[rD.k].toFixed(4)} / ${rD.s.toFixed(4)} = &lt;strong&gt;${rD.pk.toFixed(3)}&lt;/strong&gt;&lt;br&gt;
  ② L = −ln(${rD.pk.toFixed(3)}) = &lt;strong&gt;${rD.loss.toFixed(3)}&lt;/strong&gt;&lt;br&gt;
  &lt;span style="color:#555;"&gt;원-핫 정답 벡터에서 정답 클래스만 y=1이므로,
