도장 사용법




대응 이론: Ch01 들어가기 — 데이터와 모형
학번을 입력하면 나만의 문제가 나옵니다. 옆 사람과 다른 문제가 생성됩니다.
새 문제 버튼을 누르면 같은 유형의 다음 문제가 나옵니다. 무한히 연습할 수 있습니다.
답을 입력하고 채점을 켜면 즉시 확인됩니다. 막히면 풀이 보기 — 단, 먼저 손으로 계산해 보고 나서.
유형은 8개, 난이도는 [기본] → [응용] → [도전] 순입니다. 기본 3유형부터 시작하세요.
훈련 기준: 각 유형에서 연속 3문제 무실수가 되면 그 유형은 완성입니다.
// mulberry32 — 문제 번호(시드)가 같으면 항상 같은 문제가 생성된다
dojoRng = function (seed) {
  let a = (seed * 7919 + 104729) &gt;&gt;&gt; 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a &gt;&gt;&gt; 15), 1 | a);
    t = (t + Math.imul(t ^ (t &gt;&gt;&gt; 7), 61 | t)) ^ t;
    return ((t ^ (t &gt;&gt;&gt; 14)) &gt;&gt;&gt; 0) / 4294967296;
  };
}
dojoInt = (rng, lo, hi) =&gt; lo + Math.floor(rng() * (hi - lo + 1))
dojoPick = (rng, arr) =&gt; arr[Math.floor(rng() * arr.length)]
// 정답 비교 — tol 이내면 정답 처리 (학생의 반올림 오차 허용)
dojoOk = (user, answer, tol = 0.005) =&gt;
  user !== null && user !== undefined && Number.isFinite(user) && Math.abs(user - answer) &lt;= tol
dojoMark = (label, ok, answerShown) =&gt; `
  &lt;div style="display:flex;align-items:center;gap:0.5em;padding:0.25em 0;"&gt;
    &lt;span style="font-size:1.1em;"&gt;${ok ? "✅" : "❌"}&lt;/span&gt;
    &lt;span style="font-weight:600;"&gt;${label}&lt;/span&gt;
    &lt;span style="color:${ok ? "#2E7D32" : "#8C1515"};"&gt;
      ${ok ? "정답" : (answerShown != null ? "오답 — 다시 계산해 보세요" : "오답")}
    &lt;/span&gt;
  &lt;/div&gt;`
// 문제 카드
dojoProblem = (title, bodyHtml) =&gt; html`
