simCalc = {
  const a = embWords.find(d =&gt; d.word === wordA);
  const b = embWords.find(d =&gt; d.word === wordB);
  const dot = a.x * b.x + a.y * b.y;
  const na = Math.hypot(a.x, a.y);
  const nb = Math.hypot(b.x, b.y);
  return { a, b, dot, na, nb, cos: dot / (na * nb) };
}









