    .attr("text-anchor", "middle").attr("font-size", "12").attr("fill", "#555").attr("font-weight", "600").text("커널 (3×3)");

  for (let r = 0; r &lt; 3; r++) {
    for (let c = 0; c &lt; 3; c++) {
      svg.append("rect")
        .attr("x", kerX + c * (cs + gap)).attr("y", kerY + r * (cs + gap))
        .attr("width", cs).attr("height", cs).attr("rx", 3)
        .attr("fill", "#FFE0B2").attr("stroke", "#E65100").attr("stroke-width", 1.5);
      svg.append("text")
        .attr("x", kerX + c * (cs + gap) + cs / 2)
        .attr("y", kerY + r * (cs + gap) + cs / 2 + 5)
        .attr("text-anchor", "middle").attr("font-size", "14").attr("fill", "#333")
        .text(conv_ker[r][c]);
    }
  }

  // --- Feature Map (3x3) ---
  const fmX = 540, fmY = 60;
  svg.append("text").attr("x", fmX + 1.5 * (cs + gap)).attr("y", 50)
    .attr("text-anchor", "middle").attr("font-size", "12").attr("fill", "#555").attr("font-weight", "600").text("특성 맵 (3×3)");

  for (let r = 0; r &lt; 3; r++) {
    for (let c = 0; c &lt; 3; c++) {
      const filled = r * 3 + c &lt;= convStep;
      const isCurrent = r === kr && c === kc;
      svg.append("rect")
        .attr("x", fmX + c * (cs + gap)).attr("y", fmY + r * (cs + gap))
        .attr("width", cs).attr("height", cs).attr("rx", 3)
        .attr("fill", isCurrent ? "#FFCDD2" : filled ? "#FFEBEE" : "#fafafa")
        .attr("stroke", isCurrent ? "#C62828" : filled ? "#E57373" : "#ccc")
        .attr("stroke-width", isCurrent ? 2.5 : 1);
