          .attr("y", fmY + r * (cs + gap) + cs / 2 + 5)
          .attr("text-anchor", "middle").attr("font-size", "14")
          .attr("fill", isCurrent ? "#C62828" : "#333").attr("font-weight", isCurrent ? "700" : "400")
          .text(conv_fmap[r][c]);
      }
    }
  }

  // --- Calculation ---
  const prods = step.products;
  const patchVals = [];
  for (let r = 0; r &lt; 3; r++)
    for (let c = 0; c &lt; 3; c++)
      patchVals.push(conv_img[kr + r][kc + c]);

  const kerVals = [].concat(...conv_ker);
  const terms = patchVals.map((v, i) =&gt; `${v}×${kerVals[i]}`).join(" + ");

  svg.append("text").attr("x", W / 2).attr("y", H - 20)
    .attr("text-anchor", "middle").attr("font-size", "11").attr("fill", "#555")
    .text(`${terms} = ${step.result}`);

  // Multiply symbol
  svg.append("text").attr("x", 262).attr("y", 130)
    .attr("text-anchor", "middle").attr("font-size", "20").attr("fill", "#555").text("⊗");

  // Equals
  svg.append("text").attr("x", 510).attr("y", 130)
    .attr("text-anchor", "middle").attr("font-size", "20").attr("fill", "#555").text("=");

  return svg.node();
}






