    for (const y1 of positions[l]) {
      for (const y2 of positions[l + 1]) {
        svg += `&lt;line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${l===0?'#B0BEC5':'#BCAAA4'}" stroke-width="0.8" opacity="0.6"/&gt;`
      }
    }
  }

  // Draw nodes
