    for (let i = 0; i &lt; layers[l]; i++) {
      const y = positions[l][i]
      svg += `&lt;circle cx="${xPos[l]}" cy="${y}" r="${r}" fill="${fills[l]}" stroke="${colors[l]}" stroke-width="1.8"/&gt;`
    }
  }

  // Weight count annotations
  const midX1 = (xPos[0] + xPos[1]) / 2
  const midX2 = (xPos[1] + xPos[2]) / 2
  svg += `&lt;text x="${midX1}" y="${H-8}" text-anchor="middle" font-size="9" fill="#8C1515" font-weight="600"&gt;${nnW1}개 가중치 + ${nnB1}개 편향&lt;/text&gt;`
