      ∂L/∂θ₁ = 2(θ₁−2) = 2(${gd2dCur.t1.toFixed(2)}−2) = &lt;strong&gt;${gd2dCur.g1.toFixed(4)}&lt;/strong&gt;&lt;br&gt;
      ∂L/∂θ₂ = 6(θ₂−1) = 6(${gd2dCur.t2.toFixed(2)}−1) = &lt;strong&gt;${gd2dCur.g2.toFixed(4)}&lt;/strong&gt;
    &lt;/span&gt;
    &lt;div style="margin-top:0.3em;padding:0.3em 0.5em;background:white;border-radius:4px;font-size:0.9em;"&gt;
      ∇L = &lt;strong&gt;(${gd2dCur.g1.toFixed(2)}, ${gd2dCur.g2.toFixed(2)})&lt;/strong&gt;
      &lt;span style="color:#C62828;"&gt; ← 빨간 화살표&lt;/span&gt;
    &lt;/div&gt;
  &lt;/div&gt;

  &lt;div style="padding:0.5em 0.7em;background:#E8F5E9;border-radius:6px;
    border:1px solid #A5D6A7;line-height:1.8;"&gt;
    &lt;div style="font-weight:700;color:#2E7D32;margin-bottom:0.2em;"&gt;
      파라미터 갱신
    &lt;/div&gt;
    &lt;span style="font-size:0.9em;"&gt;
      θ₁' = ${gd2dCur.t1.toFixed(2)} − ${gd2dEta.toFixed(2)}×(${gd2dCur.g1.toFixed(2)}) = &lt;strong&gt;${gd2dCur.t1_new.toFixed(4)}&lt;/strong&gt;&lt;br&gt;
      θ₂' = ${gd2dCur.t2.toFixed(2)} − ${gd2dEta.toFixed(2)}×(${gd2dCur.g2.toFixed(2)}) = &lt;strong&gt;${gd2dCur.t2_new.toFixed(4)}&lt;/strong&gt;
    &lt;/span&gt;
  &lt;/div&gt;
  ` : html`
  &lt;div style="padding:0.5em 0.7em;background:#E8F5E9;border-radius:6px;
