유형 D — 이 퍼셉트론은 무슨 게이트인가 [응용]

viewof pD_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







pD_seed = dojoSeed(dojoSid, 2, "D", pD_round)







pD = {
  const rng = dojoRng(pD_seed + 200000);
  const gates = {
    "AND":  [-0.7,  0.5,  0.5],
    "OR":   [-0.3,  0.5,  0.5],
    "NAND": [ 0.7, -0.5, -0.5],
    "NOR":  [ 0.3, -0.5, -0.5],
  };
  const name = dojoPick(rng, Object.keys(gates));
  const scale = dojoPick(rng, [0.6, 0.8, 1.0, 1.2, 1.4]);
  const [w0, w1, w2] = gates[name].map(v =&gt; Math.round(v * scale * 100) / 100);
  const rows = [[0,0],[1,0],[0,1],[1,1]].map(([x1, x2]) =&gt; {
    const z = Math.round((w0 + w1 * x1 + w2 * x2) * 100) / 100;
    return { x1, x2, z, y: z &gt;= 0 ? 1 : 0 };
  });
  return { name, w0, w1, w2, rows };
}







