유형 F — 2층 MLP 순전파 [도전]

viewof pF_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







pF_seed = dojoSeed(dojoSid, 2, "F", pF_round)







pF = {
  const rng = dojoRng(pF_seed + 400000);
  const g = arr =&gt; arr.map(v =&gt; Math.round(v * 100) / 100);
  const h1 = g([dojoInt(rng, -8, 8) / 10, dojoInt(rng, 2, 8) / 10, dojoInt(rng, -8, 8) / 10]);
  const h2 = g([dojoInt(rng, -8, 8) / 10, dojoInt(rng, -8, -2) / 10, dojoInt(rng, 2, 8) / 10]);
  const o  = g([dojoInt(rng, -8, 8) / 10, dojoInt(rng, 2, 8) / 10, dojoInt(rng, 2, 8) / 10]);
  const x1 = dojoInt(rng, 0, 1), x2 = dojoInt(rng, 0, 1);
  const z1 = Math.round((h1[0] + h1[1] * x1 + h1[2] * x2) * 100) / 100;
  const s1 = z1 &gt;= 0 ? 1 : 0;
  const z2 = Math.round((h2[0] + h2[1] * x1 + h2[2] * x2) * 100) / 100;
  const s2 = z2 &gt;= 0 ? 1 : 0;
  const z3 = Math.round((o[0] + o[1] * s1 + o[2] * s2) * 100) / 100;
  const y = z3 &gt;= 0 ? 1 : 0;
  return { h1, h2, o, x1, x2, z1, s1, z2, s2, z3, y };
}







