sC_seed = dojoSeed(dojoSid, 4, "C", sC_round)







sC = {
  const rng = dojoRng(sC_seed);
  const v = [];
  for (let i = 0; i &lt; 4; i++) v.push(dojoInt(rng, 20, 60));
  const need = (5 * dojoInt(rng, 25, 50)) - v.reduce((a, b) =&gt; a + b, 0);
  v.push(need &gt;= 10 && need &lt;= 80 ? need : 40);
  const mu = v.reduce((a, b) =&gt; a + b, 0) / 5;
  const varr = v.reduce((a, b) =&gt; a + Math.pow(b - mu, 2), 0) / 5;
  const s = Math.sqrt(varr);
  const j = dojoInt(rng, 0, 4);
  return { v, mu, varr, s, j, x: v[j], z: Math.round((v[j] - mu) / s * 1000) / 1000 };
}







