    h: Math.round(h * 10000) / 10000,
    yh: Math.round(yh * 10000) / 10000,
    dLdy: Math.round(dLdy * 10000) / 10000,
    gw2: Math.round(dLdy * h * 1000) / 1000,
    gb2: Math.round(dLdy * 1000) / 1000
