viewof sH_round = Inputs.button("새 문제", { value: 0, reduce: (v) =&gt; v + 1 })







sH_seed = dojoSeed(dojoSid, 4, "H", sH_round)







sH = {
  const rng = dojoRng(sH_seed);
  const k = dojoInt(rng, 3, 4);
  const v = [];
  for (let i = 0; i &lt; k; i++) v.push(dojoInt(rng, 4, 25) / 100);
  const prod = v.reduce((a, b) =&gt; a * b, 1);
  const nMax = Math.ceil(Math.log(0.001) / Math.log(0.25));
  return { k, v, prod: Math.round(prod * 1000000) / 1000000, nMax };
}







